xml.Script:
        clYellow  := 'FFFF00';
        clBlue    := '0000A0';
        clOrange  := 'FF6000';
        clRed     := 'FF0000';
        clGreen   := '008000';
        clWhite   := 'FFFFFF';
        clViolett := '800080';

        H := 0.4;
        R := H * sqrt(2 * (1 + 1 / sqrt(5)));
        D := H * 1.1;

        for i := 0 to 4 do begin
            x[i] := R * cos(2 * Pi / 5 * i);
            y[i] := R * sin(2 * Pi / 5 * i);
        end;

        A1 := ArcCos((sqrt(5) - 5) / 8);
        A2 := ArcCos(-(1 + 5 * sqrt(5)) / 16);
